(()=>{
let identity=null,avatar=null,loading=false,busy=false,status='',name='',rerender=()=>{},generation=0;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const photoUrl=()=>'/api/avatar?v='+encodeURIComponent(avatar?.updatedAt||'');
function paint(nextName=name){name=nextName;const photo=document.querySelector('#account-avatar'),fallback=document.querySelector('#account-avatar-fallback');if(!photo||!fallback)return;fallback.textContent=(name||identity||'B').trim().charAt(0).toUpperCase();fallback.hidden=!!avatar;photo.hidden=!avatar;if(avatar&&photo.getAttribute('src')!==photoUrl())photo.src=photoUrl();if(!avatar)photo.removeAttribute('src');photo.onerror=()=>{photo.hidden=true;fallback.hidden=false}}
function refresh(){paint();if(location.hash.startsWith('#account'))rerender()}
async function sync(account,onChange){rerender=onChange;const next=account?.ready&&account.signedIn?account.email:null;if(next===identity)return;window.BoraAvatarCrop?.cancel();const gen=++generation;identity=next;avatar=null;busy=false;loading=false;status='';paint();if(!next)return;loading=true;try{const r=await fetch('/api/avatar?meta=1',{credentials:'same-origin',cache:'no-store'}),data=await r.json();if(gen!==generation)return;if(!r.ok)throw Error(data.error||'Фото пока недоступно.');avatar=data.avatar}catch(e){if(gen===generation)status=e.message}finally{if(gen===generation){loading=false;refresh()}}}
function panel(){return `<section class="profile-photo" aria-label="Фотография профиля"><div>${avatar?`<img class="account-avatar profile-photo-preview" src="${esc(photoUrl())}" alt="Твоя фотография">`:`<span class="account-avatar profile-photo-preview" aria-hidden="true">${esc((name||identity||'B').charAt(0).toUpperCase())}</span>`}</div><div><h2>Твоя фотография</h2><label class="btn alt avatar-picker">${busy?'Сохраняю…':'Загрузить фото'}<input id="avatar-file" type="file" accept="image/jpeg,image/png,image/webp" aria-label="Загрузить фотографию профиля" ${busy?'disabled':''}></label>${avatar?`<button type="button" class="avatar-remove" id="avatar-remove" ${busy?'disabled':''}>Удалить фото</button>`:''}<p>JPG, PNG или WebP · до 5 МБ.<br>Фото доступно только в твоём аккаунте.</p><p class="profile-photo-status" id="avatar-status" role="status" aria-live="polite">${esc(loading?'Загружаю профиль…':status)}</p></div></section>`}
async function change(method,file){if(busy)return;const gen=generation;busy=true;status='Сохраняю фотографию…';refresh();try{const body=method==='POST'?{image:file}:{},r=await fetch('/api/avatar',{method,credentials:'same-origin',headers:await window.BoraAccount.apiHeaders(),body:JSON.stringify(body)}),data=await r.json();if(gen!==generation)return;if(!r.ok)throw Error(data.error||'Не удалось изменить фото.');avatar=data.avatar;status=avatar?'Фото сохранено.':'Фото удалено.'}catch(e){if(gen===generation)status=e.message}finally{if(gen===generation){busy=false;refresh()}}}
function bind(){const input=document.querySelector('#avatar-file'),remove=document.querySelector('#avatar-remove');if(input)input.onchange=async()=>{const file=input.files?.[0],gen=generation;if(!file)return;input.value='';try{if(!window.BoraAvatarCrop)throw Error('Обнови страницу и выбери фото ещё раз.');const image=await window.BoraAvatarCrop.open(file);if(image&&gen===generation)await change('POST',image)}catch(e){if(gen===generation){status=e.message||'Не удалось открыть фото.';refresh()}}};if(remove)remove.onclick=()=>change('DELETE')}
window.BoraProfile={sync,paint,panel,bind};
})();
